# Daily Temperatures
# Idea: To find the daily temperatures that are warmer in the input array 'temperatures', we can use a stack. We iterate through the temperatures in reverse order, and for each temperature, we pop elements from the stack while t…
# Line comments below keep the same logic as the NeetCode 150 repo solution.

class Solution:
    def dailyTemperatures(self, temperatures: List[int]) -> List[int]:
        # Last-in-first-out pile (stack)
        stack = []
        result = [0] * len(temperatures)

        for i in range(len(temperatures) - 1, -1, -1):
            while stack and temperatures[i] >= temperatures[stack[-1]]:
                stack.pop()
            if stack:
                result[i] = stack[-1] - i
            stack.append(i)

        return result
